code_action.code:
const body=params.trigger.body;if(!body||typeof body!=='object'||Array.isArray(body))throw new Error('Cuerpo invalido');
const b=body.args&&typeof body.args==='object'&&!Array.isArray(body.args)?body.args:body;
const allowed=new Set(['event_token','action','confirmed','outcome','note','dapta_api_id','dapta_webhook']);
if(Object.keys(b).some(k=>!allowed.has(k)))throw new Error('Campo no permitido');
if(typeof b.event_token!=='string'||b.event_token.length<32||b.event_token.length>2048||!['verify_identity','outcome','optout'].includes(b.action))throw new Error('Operacion invalida');
const p={event_token:b.event_token,action:b.action};
if(b.action==='verify_identity'){if(b.confirmed!==true&&b.confirmed!=='true')throw new Error('Titular no confirmado');p.confirmed=true;}
if(b.action==='outcome'){if(!['PAID_REPORTED','PAYMENT_INTENT','WRONG_NUMBER','THIRD_PARTY','NO_CONTACT','DECLINED','OTHER'].includes(b.outcome))throw new Error('Resultado invalido');p.outcome=b.outcome;}
if(b.note!==undefined){if(typeof b.note!=='string'||b.note.length>160)throw new Error('Nota invalida');p.note=b.note;}
module.exports={payload:JSON.stringify(p)};

let d=params.enviar_operacion.response;if(typeof d==='string'){try{d=JSON.parse(d);}catch{throw new Error('Respuesta de operacion invalida');}}
if(!d||typeof d!=='object'||Array.isArray(d))throw new Error('Respuesta de operacion invalida');
module.exports={result:JSON.stringify(d)};
